<script setup lang="ts">import{ref,onMounted,computed}from'vue';import AppShell from'../components/AppShell.vue';import{api}from'../services/api';const items=ref<any[]>([]);const loading=ref(true);onMounted(async()=>{try{items.value=(await api('/api/dashboard/today')).items}catch{}finally{loading.value=false}});const c=(s:string)=>items.value.filter(x=>x.status===s).length</script>
<template><AppShell><main class="page"><div class="hero"><div><div class="title">Chào buổi sáng 👋</div><div class="muted">Mở lên là biết hôm nay cả phòng đang thế nào</div></div><router-link to="/approvals"><v-btn color="#8b0d24">Yêu cầu chờ duyệt</v-btn></router-link></div><section class="summary"><div class="card"><b>{{items.length}}</b><span>Tổng nhân sự</span></div><div class="card green"><b>{{c('WORKING')}}</b><span>Đang làm việc</span></div><div class="card amber"><b>{{c('LATE')}}</b><span>Đi muộn</span></div><div class="card red"><b>{{c('LEAVE')}}</b><span>Nghỉ phép</span></div><div class="card purple"><b>{{c('REMOTE')}}</b><span>Làm từ xa</span></div></section><h2 class="burgundy">Tình hình hôm nay</h2><div class="people card" v-if="!loading"><div class="person" v-for="p in items" :key="p.id"><v-avatar color="#fdecef">{{p.full_name?.split(' ').slice(-1)[0]?.[0]}}</v-avatar><div class="info"><b>{{p.full_name}}</b><small>{{p.department||'ITCA'}} · {{p.work_content||'Chưa cập nhật công việc'}}</small></div><span :class="['status',p.status]">{{({WORKING:'Đang làm',LATE:'Đi muộn',LEAVE:'Nghỉ phép',REMOTE:'Từ xa'} as any)[p.status]}}</span></div><div v-if="!items.length" class="muted">Chưa có dữ liệu hôm nay.</div></div><h2 class="burgundy">Thao tác nhanh</h2><div class="actions"><router-link to="/work"><v-icon>mdi-briefcase-edit</v-icon>Cập nhật công việc</router-link><router-link to="/leave?type=LATE"><v-icon>mdi-clock-alert</v-icon>Xin đi muộn</router-link><router-link to="/leave?type=MORNING_LEAVE"><v-icon>mdi-weather-sunset-up</v-icon>Nghỉ buổi sáng</router-link><router-link to="/leave?type=EARLY_LEAVE"><v-icon>mdi-exit-run</v-icon>Xin về sớm</router-link></div></main></AppShell></template>
<style scoped>.hero{display:flex;justify-content:space-between;align-items:center;margin:8px 0 22px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.summary .card{text-align:center}.summary b{display:block;font-size:30px;color:#8b0d24}.summary span{font-size:13px}.green b{color:#16a34a}.amber b{color:#f59e0b}.red b{color:#ef4444}.purple b{color:#7c3aed}.person{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid #f2f2f2}.person:last-child{border:0}.info{flex:1}.info small{display:block;color:#697386;margin-top:3px}.actions{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.actions a{background:white;border:1px solid #f1d9de;border-radius:16px;padding:20px 12px;text-decoration:none;color:#8b0d24;font-weight:700;text-align:center}.actions .v-icon{display:block;margin:0 auto 8px}@media(max-width:700px){.hero .v-btn{display:none}.summary{grid-template-columns:repeat(2,1fr)}.summary .card:first-child{grid-column:span 2}.actions{grid-template-columns:repeat(2,1fr)}}</style>
